package dashboard.enterprise.agent.connector.provider.github;
import com.fasterxml.jackson.databind.JsonNode; import dashboard.enterprise.agent.connector.credential.CredentialResolver; import dashboard.enterprise.agent.connector.model.*; import dashboard.enterprise.agent.connector.provider.AbstractLiveRestConnectorProvider; import dashboard.enterprise.agent.integration.source.model.*;
import java.net.http.HttpRequest; import java.util.*;
public final class GitHubLiveConnectorProvider extends AbstractLiveRestConnectorProvider {
 private final String owner; private final String repository;
 public GitHubLiveConnectorProvider(String endpoint,String owner,String repository,CredentialResolver resolver){super(new ConnectorDefinition("mapaf.connector.definition/v1","github-live","GitHub Live","GITHUB",ConnectorMode.LIVE,List.of("repository.change.read","pull-request.read","pipeline.status.read"),List.of(new SecretReference("mapaf.connector.secret/v1","token","GITHUB_TOKEN"))),new ConnectorConnection("mapaf.connector.connection/v1","github-live-connection",endpoint,ConnectorMode.LIVE,Map.of("owner",owner,"repository",repository)),90,resolver);this.owner=owner;this.repository=repository;}
 protected HttpRequest buildRequest(ConnectorRequest r){String id=String.valueOf(r.parameters().getOrDefault("id","1"));String path=switch(r.capabilityId()){case "repository.change.read"->"/repos/"+owner+"/"+repository+"/commits/"+id;case "pull-request.read"->"/repos/"+owner+"/"+repository+"/pulls/"+id;case "pipeline.status.read"->"/repos/"+owner+"/"+repository+"/actions/runs/"+id;default->throw new IllegalArgumentException("Unsupported capability: "+r.capabilityId());};return HttpRequest.newBuilder(uri(path)).header("Authorization","Bearer "+secret("token")).header("Accept","application/vnd.github+json").GET().build();}
 protected Map<String,Object> normalize(String capability,JsonNode n){if("pull-request.read".equals(capability)){PullRequest pr=new PullRequest("mapaf.pull-request/v1","github",n.path("number").asText(),n.path("title").asText(),n.path("body").asText(),n.path("head").path("ref").asText(),n.path("base").path("ref").asText(),n.path("state").asText(),n.path("mergeable").asBoolean(),List.of(),List.of());return Map.of("pullRequest",pr);}if("repository.change.read".equals(capability)){RepositoryChange c=new RepositoryChange("mapaf.repository.change/v1","github",repository,n.path("commit").path("tree").path("sha").asText(),n.path("sha").asText(),n.path("commit").path("author").path("name").asText(),n.path("files").size(),n.path("stats").path("additions").asInt(),n.path("stats").path("deletions").asInt(),List.of(),n.path("commit").path("author").path("date").asText());return Map.of("repositoryChange",c);}return Map.of("payload",MAPPER.convertValue(n,Map.class));}}
